for name,source in {'test_openbmi_manifest.py': "import pytest\nfrom p3a.data.openbmi_manifest import build_subject_manifest,validate_evaluation_binding\n\ndef ids(subject,phase,n):return [f'openbmi_candidate:s{subject:02d}_session1:{phase}:{i:03d}' for i in range(n)]\ndef build(subject=37):return build_subject_manifest(subject,ids(subject,'train',33),ids(subject,'test',36),'a'*64,'b'*64)\n\ndef test_manifest_identity_target_and_binding():\n    m=build()\n    assert m==build()\n    assert len(m['targets'])==36\n    assert all(0<=t['target']<36 and t['target']!=t['intended'] for t in m['targets'])\n    assert validate_evaluation_binding(m,'b'*64,37,ids(37,'test',36))\n    with pytest.raises(ValueError):validate_evaluation_binding(m,'c'*64,37,ids(37,'test',36))\n    with pytest.raises(ValueError):validate_evaluation_binding(m,'b'*64,37,list(reversed(ids(37,'test',36))))\n    with pytest.raises(ValueError):validate_evaluation_binding(build(19),'b'*64,19,ids(19,'test',36))\n\ndef test_manifest_rejects_unavailable_or_fabricated_identity():\n    with pytest.raises(ValueError):build(52)\n    with pytest.raises(ValueError):build_subject_manifest(37,ids(38,'train',33),ids(37,'test',36),'a'*64,'b'*64)\n", 'src/p3a/data/trial.py': '"""Unified trial representation shared by every dataset loader."""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\n\nimport numpy as np\n\nfrom .layout import Layout\n\n\n@dataclass\nclass Trial:\n    """One character-selection trial.\n\n    eeg:          raw EEG [channels, time], float32, before any preprocessing\n    onsets:       flash onset sample indices [F]\n    flash_groups: bool [F, n_symbols], symbols lit by each flash\n    flash_codes:  dataset-native stimulus code per flash [F] (row/col code for Comp III)\n    """\n\n    eeg: np.ndarray\n    fs: float\n    onsets: np.ndarray\n    flash_groups: np.ndarray\n    flash_codes: np.ndarray\n    target_symbol: str\n    layout: Layout\n    subject_id: str\n    dataset: str\n    trial_index: int\n    source_split: str  # official split in the source release: "train" or "test"\n    channel_names: list[str] = field(default_factory=list)\n\n    @property\n    def trial_id(self) -> str:\n        return f"{self.dataset}:{self.subject_id}:{self.source_split}:{self.trial_index:03d}"\n\n    @property\n    def n_flashes(self) -> int:\n        return len(self.onsets)\n\n    def target_flash_mask(self, symbol: str | None = None) -> np.ndarray:\n        """Flashes that contain `symbol` (default: the trial\'s own target)."""\n        k = self.layout.index(symbol or self.target_symbol)\n        return self.flash_groups[:, k]\n', 'src/p3a/data/layout.py': '"""Speller layouts and the flash-group representation.\n\nA flash group is the set of symbols lit by one flash. Row/column spellers are\nthe special case where each group is one row or one column.\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\n\nimport numpy as np\n\n\n@dataclass(frozen=True)\nclass Layout:\n    layout_id: str\n    symbols: str\n    n_rows: int\n    n_cols: int\n\n    @property\n    def n_symbols(self) -> int:\n        return len(self.symbols)\n\n    def index(self, symbol: str) -> int:\n        i = self.symbols.find(symbol)\n        if i < 0:\n            raise KeyError(f"symbol {symbol!r} not in layout {self.layout_id}")\n        return i\n\n    def row_col(self, symbol: str) -> tuple[int, int]:\n        return divmod(self.index(symbol), self.n_cols)\n\n\n# BCI Competition III Dataset II: codes 1-6 = columns (left to right), 7-12 = rows (top to bottom).\nCOMP3 = Layout("rc6x6_comp3", "ABCDEFGHIJKLMNOPQRSTUVWXYZ123456789_", 6, 6)\n\n\ndef rc_code_to_group(layout: Layout, code: int) -> np.ndarray:\n    """Boolean mask over symbols lit by a row/column stimulus code (Comp III convention)."""\n    group = np.zeros(layout.n_symbols, dtype=bool)\n    if 1 <= code <= layout.n_cols:\n        group[code - 1 :: layout.n_cols] = True\n    elif layout.n_cols < code <= layout.n_cols + layout.n_rows:\n        r = code - layout.n_cols - 1\n        group[r * layout.n_cols : (r + 1) * layout.n_cols] = True\n    else:\n        raise ValueError(f"invalid row/column code {code}")\n    return group\n\n\ndef symbol_rc_codes(layout: Layout, symbol: str) -> tuple[int, int]:\n    """(row_code, col_code) for a symbol under the Comp III convention."""\n    r, c = layout.row_col(symbol)\n    return layout.n_cols + 1 + r, c + 1\n', 'src/p3a/data/openbmi_manifest.py': '"""Build candidate manifests from cloud-verified loader identities, never EEG."""\nimport hashlib\nfrom p3a.data.openbmi_partitions import candidate_character_partition,candidate_subject_role\n\nTRAIN_PHRASE=\'NEURAL_NETWORKS_AND_DEEP_LEARNING\'\nTEST_PHRASE=\'PATTERN_RECOGNITION_MACHINE_LEARNING\'\n\ndef build_subject_manifest(subject,train_ids,test_ids,raw_sha256,protocol_sha256,seed=20261013):\n    role=candidate_subject_role(subject)\n    for digest in (raw_sha256,protocol_sha256):\n        if len(digest)!=64 or any(c not in \'0123456789abcdef\' for c in digest):\n            raise ValueError(\'explicit lowercase SHA256 provenance required\')\n    if subject==52:\n        raise ValueError(\'subject52 calibrated manifest unavailable; retain in flow separately\')\n    expected=lambda phase,n:[f\'openbmi_candidate:s{subject:02d}_session1:{phase}:{i:03d}\' for i in range(n)]\n    if train_ids!=expected(\'train\',33) or test_ids!=expected(\'test\',36):\n        raise ValueError(\'exact cloud-validated stored-order official phase IDs required\')\n    partition=candidate_character_partition(train_ids,test_ids,seed)\n    # The loader layout is authoritative; phrases here only identify intended symbols.\n    from p3a.data.loaders.openbmi import LAYOUT\n    targets=[]\n    for trial_id,symbol in zip(test_ids,TEST_PHRASE):\n        intended=LAYOUT.index(symbol)\n        draw=int(hashlib.sha256((str(seed)+\':\'+trial_id).encode()).hexdigest(),16)%35\n        targets.append(dict(trial_id=trial_id,intended=intended,target=draw+(draw>=intended)))\n    return dict(subject=subject,session=1,role=role,seed=seed,partition=partition,targets=targets,\n                raw_sha256=raw_sha256,protocol_sha256=protocol_sha256,\n                status=\'candidate metadata manifest; does not unlock independent performance\')\n\ndef validate_evaluation_binding(manifest,protocol_sha256,subject,trial_ids):\n    if subject==52 or manifest[\'subject\']!=subject or manifest[\'role\']!=\'evaluation\':\n        raise ValueError(\'eligible sealed evaluation identity required\')\n    if manifest[\'protocol_sha256\']!=protocol_sha256:\n        raise ValueError(\'protocol hash mismatch\')\n    if manifest[\'partition\'][\'evaluation\']!=trial_ids:\n        raise ValueError(\'exact evaluation identity/order mismatch\')\n    from p3a.data.openbmi_partitions import validate_partition\n    validate_partition(manifest[\'partition\'])\n    return True\n', 'src/p3a/data/openbmi_partitions.py': '"""Candidate partitions only; no frozen-file generation on import."""\nimport numpy as np\n\n\ndef candidate_character_partition(train_ids,test_ids,seed):\n    if len(train_ids)!=33 or len(test_ids)!=36:\n        raise ValueError(\'documented33 train/36 test characters required\')\n    if len(set(train_ids+test_ids))!=69:\n        raise ValueError(\'unique disjoint official phase IDs required\')\n    order=np.random.default_rng(seed).permutation(33)\n    result={\'normalization\':sorted(train_ids[i] for i in order[:13]),\n            \'calibration\':sorted(train_ids[i] for i in order[13:]),\n            \'evaluation\':list(test_ids)}\n    validate_partition(result)\n    return result\n\n\ndef validate_partition(partition):\n    required={\'normalization\':13,\'calibration\':20,\'evaluation\':36}\n    if set(partition)!=set(required): raise ValueError(\'unexpected partition roles\')\n    all_ids=[]\n    for key,n in required.items():\n        ids=partition[key]\n        if len(ids)!=n or not all(isinstance(i,str) and i for i in ids):\n            raise ValueError(\'invalid role count or identity\')\n        all_ids.extend(ids)\n    if len(set(all_ids))!=len(all_ids): raise ValueError(\'role leakage or duplicate IDs\')\n\n\ndef candidate_subject_role(subject):\n    if not isinstance(subject,int) or not 1<=subject<=54:\n        raise ValueError(\'documented subject ID1..54 required\')\n    return \'development\' if subject<=18 else \'validation\' if subject<=36 else \'evaluation\'\n', 'src/p3a/data/loaders/openbmi.py': '"""Bounded OpenBMI character loader candidate; stored event order preserved."""\nimport numpy as np\nfrom p3a.data.layout import Layout\nfrom p3a.data.trial import Trial\n\nLAYOUT = Layout(\'openbmi_schedule36\',\'ABCDEFGHIJKLMNOPQRSTUVWXYZ123456789_\',6,6)\n\n\ndef build_trials(data, schedule, phrase, subject, session, split):\n    if len(schedule)<5: raise ValueError(\'five schedule entries required\')\n    for a in schedule[:5]:\n        a=np.asarray(a)\n        if a.shape!=(12,6) or not np.isfinite(a).all() or not np.all(a==np.floor(a)):\n            raise ValueError(\'finite integer12x6 schedule required\')\n    groups_raw=np.concatenate([np.asarray(a,dtype=int) for a in schedule[:5]],axis=0)\n    if groups_raw.shape != (60,6) or groups_raw.min()<1 or groups_raw.max()>36:\n        raise ValueError(\'invalid five-sequence schedule\')\n    groups=np.zeros((60,36),dtype=bool)\n    for i,row in enumerate(groups_raw):\n        if len(set(row))!=6: raise ValueError(\'duplicate symbol within flash\')\n        groups[i,row-1]=True\n    if not np.all(groups.sum(axis=0)==10): raise ValueError(\'invalid symbol coverage\')\n    x=np.asarray(data[\'x\']); t=np.asarray(data[\'t\']).ravel()\n    labels=np.asarray(data[\'y_dec\']).ravel(); fs=float(data[\'fs\'])\n    channels=[str(v) for v in np.asarray(data[\'chan\']).ravel()]\n    if not np.isfinite(fs) or fs<=0: raise ValueError(\'positive finite sampling rate required\')\n    if not phrase or any(c not in LAYOUT.symbols for c in phrase): raise ValueError(\'invalid phrase\')\n    if x.ndim!=2 or x.shape[1]!=len(channels) or len(set(channels))!=len(channels):\n        raise ValueError(\'unaligned or duplicate channels\')\n    if not np.isfinite(t).all() or not np.isin(labels,[1,2]).all():\n        raise ValueError(\'invalid event values or binary labels\')\n    if not np.all(t==np.floor(t)) or len(t)!=60*len(phrase) or len(labels)!=len(t):\n        raise ValueError(\'unaligned integer event/character counts\')\n    t=t.astype(np.int64)-1\n    if x.ndim!=2 or not np.isfinite(x).all() or np.any(t<0) or np.any(t>=len(x)):\n        raise ValueError(\'invalid signal/index bounds\')\n    if len(set(t.tolist()))!=len(t): raise ValueError(\'duplicate event indices\')\n    trials=[]\n    for i,symbol in enumerate(phrase):\n        on=t[i*60:(i+1)*60]; lab=labels[i*60:(i+1)*60]\n        if not np.array_equal(groups[:,LAYOUT.index(symbol)],lab==1):\n            raise ValueError(\'schedule and true-character labels disagree\')\n        start=max(0,int(on.min())-int(.2*fs)); end=int(on.max())+int(fs)+1\n        if end>len(x): raise ValueError(\'post-flash epoch exceeds recording\')\n        trials.append(Trial(eeg=x[start:end].T.astype(np.float32),fs=fs,\n            onsets=on-start,flash_groups=groups.copy(),flash_codes=np.tile(np.arange(1,13),5),\n            target_symbol=symbol,layout=LAYOUT,subject_id=f\'s{subject:02d}_session{session}\',\n            dataset=\'openbmi_candidate\',trial_index=i,source_split=split,\n            channel_names=[str(v) for v in np.asarray(data[\'chan\']).ravel()]))\n    return trials\n'}.items():
    target=base/name;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(source)
