# Metadata-only verification runs in Kaggle after synthetic checks.

import base64,zlib
INPUTS={'coverage_1_51': '', 'coverage_52_54': '', 'protocol': ''}

sys.path.insert(0,str(base/'src'))
from p3a.data.openbmi_manifest import build_subject_manifest
raw_inputs={name:zlib.decompress(base64.b64decode(value)) for name,value in INPUTS.items()}
protocol_sha=hashlib.sha256(raw_inputs['protocol']).hexdigest()
def find_key(obj,key):
    if isinstance(obj,dict):
        if key in obj:return obj[key]
        for value in obj.values():
            result=find_key(value,key)
            if result is not None:return result
    elif isinstance(obj,list):
        for value in obj:
            result=find_key(value,key)
            if result is not None:return result
records={}
for name in ('coverage_1_51','coverage_52_54'):
    for record in json.loads(raw_inputs[name]):
        key=(record['subject'],record['split'])
        if key in records:assert records[key]==record
        records[key]=record
manifests=[];flow=[]
for subject in range(1,55):
    train=records[(subject,'train')];test=records[(subject,'test')]
    assert train['session']==test['session']==1
    if subject==52:
        assert find_key(train,'original_order_mismatch_count')==528
        assert find_key(train,'loader_error')=='schedule and true-character labels disagree'
        flow.append(dict(subject=52,status='calibrated estimand unavailable; retained in evaluation flow'))
        continue
    assert find_key(train,'original_order_mismatch_count')==find_key(test,'original_order_mismatch_count')==0
    assert train['file_sha256']==test['file_sha256']
    assert find_key(train,'loader_trial_count')==33 and find_key(test,'loader_trial_count')==36
    manifests.append(build_subject_manifest(subject,find_key(train,'loader_trial_ids'),find_key(test,'loader_trial_ids'),train['file_sha256'],protocol_sha))
    flow.append(dict(subject=subject,status='metadata identity eligible'))
result=dict(status='CANDIDATE ONLY; no performance unlock, not final frozen protocol',protocol_sha256=protocol_sha,input_sha256={k:hashlib.sha256(v).hexdigest() for k,v in raw_inputs.items()},manifests=manifests,flow=flow)
(out/'candidate_metadata_manifests.json').write_text(json.dumps(result,indent=2))
(out/'metadata_verification.md').write_text('# Metadata candidate verification\n\nAll54 subject records checked;53 eligible metadata manifests, including17 evaluation users; subject52 retained with unavailable calibrated estimand. All exact stored-order identities and independent partitions checked. This does not unlock performance or freeze an incomplete protocol.\n')
print('Metadata manifest verification complete; gate CLOSED')
